// ✓ 겉으로 드러나는 약속을 확인 — 안을 바꿔도 산다
expect(total([{ price: 1000, n: 2 }])).toBe(2000);
expect(total([])).toBe(0);                  // 경계값

// ✗ 구현 세부를 확인 — 리팩터링마다 깨진다
expect(calcSpy).toHaveBeenCalledTimes(2);

// ✗ 남의 라이브러리를 확인
expect(JSON.parse('{"a":1}').a).toBe(1);

const results = [];
function it(name, fn) {
  try { fn(); results.push([name, true]); }
  catch (e) { results.push([name, false, e.message]); }
}
function expect(actual) {
  return {
    toBe(want) {
      if (actual !== want) throw new Error(`기대 ${JSON.stringify(want)} · 실제 ${JSON.stringify(actual)}`);
    },
    toThrow() {
      let threw = false;
      try { actual(); } catch { threw = true; }
      if (!threw) throw new Error('던질 줄 알았는데 안 던졌다');
    },
  };
}

// … it(...) 들 …

const fail = results.filter((r) => !r[1]);
console.log(`${results.length - fail.length}/${results.length} 통과`);
fail.forEach(([n, , m]) => console.log('FAIL', n, m));
if (fail.length) process.exit(1);      // ← 이 한 줄이 검사기를 만든다
